Interface PaymentMethod
  Method Charge(amount As Integer) As Integer;
EndInterface

Class Cash Implements PaymentMethod
  Method Charge(amount As Integer) As Integer
    Return amount;
  EndMethod
EndClass

Class Card Implements PaymentMethod
  Method Charge(amount As Integer) As Integer
    Return amount + amount * 5 Div 100;
  EndMethod
EndClass

Subroutine ChargeWith<T: PaymentMethod>(payment As T, amount As Integer) As Integer
  Return payment.Charge(amount);
EndSubroutine

Class Product
  Define name As String;
  Define price As Integer;

  Method Constructor(productName As String, productPrice As Integer)
    This.name <- productName;
    This.price <- productPrice;
  EndMethod

  Method Amount(quantity As Integer) As Integer
    Return This.price * quantity;
  EndMethod
EndClass

Class Inventory
  Private Define stock As Vector<Integer>;

  Method Constructor()
    This.stock <- vector();
    This.stock.append(10);
    This.stock.append(5);
    This.stock.append(8);
    This.stock.append(12);
    This.stock.append(6);
  EndMethod

  Method Remaining(code As Integer) As Integer
    Return This.stock[code - 1];
  EndMethod

  Method Withdraw(code As Integer, quantity As Integer) As Boolean
    If quantity > This.stock[code - 1] Then
      Return False;
    EndIf
    This.stock[code - 1] <- This.stock[code - 1] - quantity;
    Return True;
  EndMethod
EndClass

Class Till
  Private Define total As Integer;

  Method Constructor()
    This.total <- 0;
  EndMethod

  Method AddUp(amount As Integer)
    This.total <- This.total + amount;
  EndMethod

  Method Total() As Integer
    Return This.total;
  EndMethod

  Method WithDiscount() As Integer
    Return This.total - This.total Div 10;
  EndMethod
EndClass

Subroutine Catalog() As Vector<Product>
  Define products As Vector<Product> <- vector();
  products.append(New Product("Juice", 3));
  products.append(New Product("Sandwich", 5));
  products.append(New Product("Alfajor", 2));
  products.append(New Product("Water", 1));
  products.append(New Product("Fruit", 2));
  Return products;
EndSubroutine

Algorithm Kiosk
  Define products As Vector<Product> <- Catalog();
  Define inventory As Inventory <- New Inventory();
  Define till As Till <- New Till();
  Define code, quantity As Integer;
  Read code;
  While code <> 0 Do
    Read quantity;
    If code < 1 Or code > 5 Then
      Write "Code ", code, " does not exist";
    Else
      Define product As Product <- products[code - 1];
      If quantity < 1 Then
        Write "Quantity ", quantity, " is not valid";
      Else
        If inventory.Withdraw(code, quantity) Then
          till.AddUp(product.Amount(quantity));
          Write product.name, " x ", quantity, " = ", product.Amount(quantity);
        Else
          Write product.name, " x ", quantity, " rejected: stock is ", inventory.Remaining(code);
        EndIf
      EndIf
    EndIf
    Read code;
  EndWhile
  Define payment As String;
  Read payment;
  Write "Total: ", till.Total();
  Write "With discount: ", till.WithDiscount();
  If payment = "card" Then
    Write "To pay by card: ", ChargeWith(New Card(), till.WithDiscount());
  Else
    Write "To pay in cash: ", ChargeWith(New Cash(), till.WithDiscount());
  EndIf
  Write "Final stock:";
  For i <- 1 To 5 Do
    Write products[i - 1].name, " ", inventory.Remaining(i);
  EndFor
EndAlgorithm
